/**
 * Types of the Skill Studio API, aliased from the OpenAPI schema (`schema.d.ts`, generated by `pnpm gen:api`).
 * Nothing here restates a response shape: when the API changes, regenerating the schema makes `tsc` point at
 * every place in the web app that no longer matches.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];

export type ISODateTime = string;

// Enumerations
export type Category = Schemas["SkillCategory"];
export type SkillStatus = Schemas["SkillStatus"];
export type ComputeKind = Schemas["BackendKind"];
export type StageKind = Schemas["StageKind"];
export type RunsOn = Schemas["RunsOn"];
export type LogLevel = Schemas["LogLevel"];
export type GateVerdict = Schemas["GateVerdict"];
export type ReviewStatus = Schemas["ReviewStatus"];
export type HealthStatus = Schemas["TargetHealth"]["status"];
export type Decision = Schemas["Decision"]["decision"];
export type ArtifactKind = Schemas["ArtifactKind"];
export type GateOp = Schemas["GateOp"];
export type RunStatus = Schemas["RunStatus"];
export type StageStatus = Schemas["StageStatus"];

// Resources
export type Me = Schemas["Me"];
export type UserRef = Schemas["UserRef"];
export type RunRef = Schemas["RunRef"];
export type SkillSummary = Schemas["SkillSummary"];
export type SkillPage = Schemas["SkillPage"];
export type Preset = Schemas["Preset"];
export type PipelineStageDef = Schemas["PipelineStageDef"];
export type GateCriterion = Schemas["GateCriterion"];
export type Headline = Schemas["Headline"];
export type ComputeHealth = Schemas["TargetHealth"];
export type ComputeUsage = Schemas["TargetUsage"];
export type ComputeTarget = Schemas["ComputeTarget"];
export type Estimate = Schemas["Estimate"];
export type Artifact = Schemas["Artifact"];
export type ArtifactUrl = Schemas["ArtifactUrl"];
export type Stage = Schemas["Stage"];
export type HeadlineValue = Schemas["HeadlineValue"];
export type RunSummary = Schemas["RunSummary"];
export type RunPage = Schemas["RunPage"];
export type GateCriterionResult = Schemas["GateCriterionResult"];
export type GateDecision = Schemas["GateDecision"];
export type RunPermissions = Schemas["RunPermissions"];
export type RunDetail = Schemas["RunDetail"];
export type LogLine = Schemas["LogLine"];
export type LogPage = Schemas["LogPage"];
export type MetricSeries = Schemas["MetricSeries"];
export type MetricsResponse = Schemas["Metrics"];
export type Evaluation = Schemas["Evaluation"];
export type AuditEvent = Schemas["AuditEvent"];
export type AuditEventPage = Schemas["AuditEventPage"];
