export type CreateRunRequest = Schemas["RunCreate"];
export type DecisionRequest = Schemas["Decision"];
export type AuditEventInput = Schemas["AuditEventCreate"];

/**
 * A JSON Schema document as the API produces it (pydantic's `model_json_schema()` and skill params).
 * The OpenAPI schema can only call these "an object"; this is the part of JSON Schema the forms read.
 */
export interface JsonSchema {
  type?: string | string[];
  title?: string;
  description?: string;
  default?: unknown;
  enum?: unknown[];
  const?: unknown;
  format?: string;
  minimum?: number;
  maximum?: number;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  anyOf?: JsonSchema[];
  allOf?: JsonSchema[];
  $ref?: string;
  $defs?: Record<string, JsonSchema>;
  writeOnly?: boolean;
  minLength?: number;
  additionalProperties?: boolean;
  /** Skill manifests mark warm-start parameters with `"checkpoint"`. */
  "x-kind"?: string;
}

export type SkillDetail = Omit<Schemas["SkillDetail"], "params_schema"> & { params_schema: JsonSchema };
export type ComputeTargetSchema = { config: JsonSchema; secret: JsonSchema } & Omit<
  Schemas["BackendSchema"],
  "config" | "secret"
>;

/** Server-sent events on `GET /runs/{id}/events` (SPEC §9.3); SSE payloads are not part of OpenAPI. */
export type RunEvent =
  | { type: "log"; data: LogLine }
  | { type: "metric"; data: { stage_id: string; step: number; values: Record<string, number> } }
  | { type: "stage"; data: Stage }
  | { type: "run"; data: RunSummary };
